def num_subarray_bounded_max(nums, left, right):
    n = len(nums)
    count = 0
    for start in range(n):
        current_max = 0
        for end in range(start, n):
            current_max = max(current_max, nums[end])                      # extend the subarray by one and track its running maximum directly
            if left <= current_max <= right:
                count += 1
    return count


if __name__ == "__main__":
    print(num_subarray_bounded_max([2, 1, 4, 3], 2, 3))

