import java.util.*;

public class Main {
    int numSubarrayBoundedMax(int[] nums, int left, int right) {
        int n = nums.length;
        int count = 0;
        for (int start = 0; start < n; start++) {
            int currentMax = 0;
            for (int end = start; end < n; end++) {
                currentMax = Math.max(currentMax, nums[end]);                     // extend the subarray by one and track its running maximum directly
                if (currentMax >= left && currentMax <= right) count++;
            }
        }
        return count;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(solution.numSubarrayBoundedMax(new int[]{2, 1, 4, 3}, 2, 3));
    }
}

