def num_subarray_bounded_max(nums, left, right):
    def count_at_most(bound):
        total = 0
        run = 0                                                            # length of the current run of elements all <= bound, ending here
        for x in nums:
            if x <= bound:
                run += 1                                                   # this element extends the qualifying run
            else:
                run = 0                                                    # this element is too large; the run breaks completely
            total += run                                                   # every subarray ending here, within the current run, has max <= bound
        return total

    return count_at_most(right) - count_at_most(left - 1)                  # max in [left, right] = (max <= right) minus (max <= left - 1)


if __name__ == "__main__":
    print(num_subarray_bounded_max([2, 1, 4, 3], 2, 3))

